package net.fabricmc.fabric.api.entity.event.v1;

import net.fabricmc.fabric.api.event.Event;
import net.fabricmc.fabric.api.event.EventFactory;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.Mob;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.Vec3;

/** Fabric API: sleeping in beds (start/stop/allow are fired; the rest are provided but not fired yet) (Omniloader stand-in; generated by tools/gen-fabric-events.py). */
public final class EntitySleepEvents {
    private EntitySleepEvents() {}

    public static final Event<AllowSleeping> ALLOW_SLEEPING = EventFactory.createArrayBacked(AllowSleeping.class, ls -> (player, sleepingPos) -> { for (AllowSleeping l : ls) { var r = l.allowSleep(player, sleepingPos); if (r != null) return r; } return null; });
    public static final Event<StartSleeping> START_SLEEPING = EventFactory.createArrayBacked(StartSleeping.class, ls -> (entity, sleepingPos) -> { for (StartSleeping l : ls) l.onStartSleeping(entity, sleepingPos); });
    public static final Event<StopSleeping> STOP_SLEEPING = EventFactory.createArrayBacked(StopSleeping.class, ls -> (entity, sleepingPos) -> { for (StopSleeping l : ls) l.onStopSleeping(entity, sleepingPos); });
    public static final Event<AllowBed> ALLOW_BED = EventFactory.createArrayBacked(AllowBed.class, ls -> (entity, sleepingPos, state, vanillaResult) -> { for (AllowBed l : ls) { InteractionResult r = l.allowBed(entity, sleepingPos, state, vanillaResult); if (r != InteractionResult.PASS) return r; } return InteractionResult.PASS; });
    public static final Event<AllowSleepTime> ALLOW_SLEEP_TIME = EventFactory.createArrayBacked(AllowSleepTime.class, ls -> (player, sleepingPos, vanillaResult) -> { for (AllowSleepTime l : ls) { InteractionResult r = l.allowSleepTime(player, sleepingPos, vanillaResult); if (r != InteractionResult.PASS) return r; } return InteractionResult.PASS; });
    public static final Event<AllowNearbyMonsters> ALLOW_NEARBY_MONSTERS = EventFactory.createArrayBacked(AllowNearbyMonsters.class, ls -> (player, sleepingPos, vanillaResult) -> { for (AllowNearbyMonsters l : ls) { InteractionResult r = l.allowNearbyMonsters(player, sleepingPos, vanillaResult); if (r != InteractionResult.PASS) return r; } return InteractionResult.PASS; });
    public static final Event<AllowResettingTime> ALLOW_RESETTING_TIME = EventFactory.createArrayBacked(AllowResettingTime.class, ls -> player -> { for (AllowResettingTime l : ls) if (!l.allowResettingTime(player)) return false; return true; });
    public static final Event<ModifySleepingDirection> MODIFY_SLEEPING_DIRECTION = EventFactory.createArrayBacked(ModifySleepingDirection.class, ls -> (entity, sleepingPos, sleepingDirection) -> { Direction cur = sleepingDirection; for (ModifySleepingDirection l : ls) cur = l.modifySleepDirection(entity, sleepingPos, cur); return cur; });
    public static final Event<AllowSettingSpawn> ALLOW_SETTING_SPAWN = EventFactory.createArrayBacked(AllowSettingSpawn.class, ls -> (player, sleepingPos) -> { for (AllowSettingSpawn l : ls) if (!l.allowSettingSpawn(player, sleepingPos)) return false; return true; });
    public static final Event<SetBedOccupationState> SET_BED_OCCUPATION_STATE = EventFactory.createArrayBacked(SetBedOccupationState.class, ls -> (entity, sleepingPos, bedState, occupied) -> { for (SetBedOccupationState l : ls) if (l.setBedOccupationState(entity, sleepingPos, bedState, occupied)) return true; return false; });
    public static final Event<ModifyWakeUpPosition> MODIFY_WAKE_UP_POSITION = EventFactory.createArrayBacked(ModifyWakeUpPosition.class, ls -> (entity, sleepingPos, bedState, wakeUpPos) -> { Vec3 cur = wakeUpPos; for (ModifyWakeUpPosition l : ls) cur = l.modifyWakeUpPosition(entity, sleepingPos, bedState, cur); return cur; });

    @FunctionalInterface public interface AllowSleeping { Player.BedSleepingProblem allowSleep(Player player, BlockPos sleepingPos); }
    @FunctionalInterface public interface StartSleeping { void onStartSleeping(LivingEntity entity, BlockPos sleepingPos); }
    @FunctionalInterface public interface StopSleeping { void onStopSleeping(LivingEntity entity, BlockPos sleepingPos); }
    @FunctionalInterface public interface AllowBed { InteractionResult allowBed(LivingEntity entity, BlockPos sleepingPos, BlockState state, boolean vanillaResult); }
    @FunctionalInterface public interface AllowSleepTime { InteractionResult allowSleepTime(Player player, BlockPos sleepingPos, boolean vanillaResult); }
    @FunctionalInterface public interface AllowNearbyMonsters { InteractionResult allowNearbyMonsters(Player player, BlockPos sleepingPos, boolean vanillaResult); }
    @FunctionalInterface public interface AllowResettingTime { boolean allowResettingTime(Player player); }
    @FunctionalInterface public interface ModifySleepingDirection { Direction modifySleepDirection(LivingEntity entity, BlockPos sleepingPos, Direction sleepingDirection); }
    @FunctionalInterface public interface AllowSettingSpawn { boolean allowSettingSpawn(Player player, BlockPos sleepingPos); }
    @FunctionalInterface public interface SetBedOccupationState { boolean setBedOccupationState(LivingEntity entity, BlockPos sleepingPos, BlockState bedState, boolean occupied); }
    @FunctionalInterface public interface ModifyWakeUpPosition { Vec3 modifyWakeUpPosition(LivingEntity entity, BlockPos sleepingPos, BlockState bedState, Vec3 wakeUpPos); }
}
